$string['settings:prompt_budget_mode'] = 'Режим на бюджета за системната подсказка';
$string['settings:prompt_budget_mode_desc'] = 'Как се определя бюджетът от знаци за системната подсказка. <strong>Извеждане от модела</strong> изчислява мястото, което конфигурираният модел действително предлага — контекстния му прозорец минус запазения отговор и историята на разговора — и използва него, с горна граница, за да не оправдае много голям прозорец много голяма подсказка. Това важи само докато бюджетът от знаци по-долу е оставен на стойността си по подразбиране 36 000: променете ли това число, то надделява, и в двете посоки, защото число, въведено от администратор, е решение, а не догадка. <strong>Фиксиран</strong> винаги използва числото по-долу. Самостоятелно хостван сървър трябва да зададе контекстния прозорец на бекенда, който има предимство пред всичко тук.';
$string['settings:prompt_budget_mode_auto'] = 'Извеждане от модела (препоръчително)';
$string['settings:prompt_budget_mode_fixed'] = 'Фиксиран бюджет от знаци';

$string['quizlock:scope'] = 'Докъде стига заключването';
